function genFloor(ch, seed) {
  const r = rng(seed * 31 + ch * 7919), C = CH[ch - 1];
  const boxes = [];
  const mk = (cx, cz, sx, sz, h, kind, style) => ({ x1: cx - sx / 2, x2: cx + sx / 2, y1: 0, y2: h, z1: cz - sz / 2, z2: cz + sz / 2, kind, style });
  boxes.push(mk(0, -24.5, 50, 1, CEIL, 'outer'), mk(0, 24.5, 50, 1, CEIL, 'outer'), mk(-24.5, 0, 1, 50, CEIL, 'outer'), mk(24.5, 0, 1, 50, CEIL, 'outer'));
  boxes.push(mk(-3.5, -21.5, 1, 5, CEIL, 'wall'), mk(3.5, -21.5, 1, 5, CEIL, 'wall'), mk(0, -19, 6, 0.4, CEIL, 'door'));
  const inZone = b => (b.x2 > -7 && b.x1 < 7 && b.z2 > 14) || (b.x2 > -8 && b.x1 < 8 && b.z1 < -12);
  const overlaps = (b, gap) => boxes.some(o => o.kind !== 'outer' && b.x1 < o.x2 + gap && b.x2 > o.x1 - gap && b.z1 < o.z2 + gap && b.z2 > o.z1 - gap);
  const inBounds = b => b.x1 > -22.6 && b.x2 < 22.6 && b.z1 > -22.6 && b.z2 < 22.6;
  const place = (n, maker, gap) => { let k = 0, t = 0; while (k < n && t < 500) { t++; const b = maker(); if (!inBounds(b) || inZone(b) || overlaps(b, gap)) continue; boxes.push(b); k++; } };
  const pick = a => a[Math.floor(r() * a.length)];
  place(3 + Math.min(ch, 5), () => { const hz = r() < 0.5, len = 6 + Math.floor(r() * 4) * 2; return mk(Math.round(r() * 36 - 18), Math.round(r() * 32 - 16), hz ? len : 1, hz ? 1 : len, CEIL, 'wall'); }, 1.8);
  const tallStyle = C.tall[0], wide = tallStyle === 'bookshelf';
  place(wide ? 9 : 5 + (ch % 3), () => { const rot = r() < 0.5; return mk(r() * 38 - 19, r() * 34 - 17, wide ? (rot ? 0.9 : 2.6) : 1.4, wide ? (rot ? 2.6 : 0.9) : 1.4, 3.2, 'tall', tallStyle); }, 1.7);
  place(9 + ch * 2, () => { const st = pick(C.furn), big = r() < 0.5, rot = r() < 0.5; return mk(r() * 40 - 20, r() * 36 - 18, big ? (rot ? 1.2 : 2.6) : 1.4, big ? (rot ? 2.6 : 1.2) : 1.4, 1.1, 'furn', st); }, 1.4);
  const free = (x, z, rad) => !boxes.some(b => x > b.x1 - rad && x < b.x2 + rad && z > b.z1 - rad && z < b.z2 + rad);
  const spot = (minZ, maxZ, rad, avoid) => { for (let t = 0; t < 300; t++) { const x = r() * 42 - 21, z = minZ + r() * (maxZ - minZ); if (!free(x, z, rad)) continue; if (Math.abs(x) < 4.5 && z < -13) continue; if (avoid.some(a => Math.hypot(a.x - x, a.z - z) < 4)) continue; return { x, z }; } return null; };
  const enemies = [];
  for (const t of TYPES) for (let i = 0; i < (C.roster[t] || 0); i++) {
    if (t === 'boss') { enemies.push({ t, x: 0, z: -8 }); continue; }
    for (let k = 0; k < 200; k++) { const x = r() * 42 - 21, z = r() * 30 - 21; if (!free(x, z, ET[t].r + 0.4) || enemies.some(e => Math.hypot(e.x - x, e.z - z) < 2.5) || (Math.abs(x) < 4 && z < -13)) continue; enemies.push({ t, x, z }); break; }
  }
  const chests = []; for (let i = 0; i < 3; i++) { const s = spot(-21, 14, 1.0, chests.concat([SPAWN])); if (s) chests.push(s); }
  const item = C.item ? spot(-21, 10, 0.8, chests) : null;
  const diary = spot(-21, 12, 0.8, chests.concat(item ? [item] : []));
  const portals = [], used = chests.concat(item ? [item] : [], diary ? [diary] : []);
  for (let k = 0; k < 2; k++) {
    const a = spot(-19, 12, 1.9, used.concat(portals)); if (!a) break;
    let b = null; for (let t = 0; t < 40 && !b; t++) { const c = spot(-19, 12, 1.9, used.concat(portals, [a])); if (c && Math.hypot(c.x - a.x, c.z - a.z) > 16) b = c; }
    if (!b) break; portals.push({ x: a.x, z: a.z, pair: k }, { x: b.x, z: b.z, pair: k });
  }
  portals.length = 0;
  const spawns = []; for (let k = 0; k < 12; k++) { const sp = spot(-21, 21, 0.9, spawns); if (sp) spawns.push(sp); }
  return { boxes, enemies, chests, item, diary, portals, spawns };
}

