let levelBoxes = [], pieceBoxes = [], ramps = [], allBoxes = [];
const doorClosed = () => !world || world.ph === 'prep' || world.ph === 'fight';
const solidBox = b => b.kind !== 'door' || (b.did !== undefined ? !doorOpenBit(b.did) : doorClosed());
function rebuildAllBoxes() { allBoxes = levelBoxes.concat(pieceBoxes); }
function collides(x, z, rad, feet) {
  for (const b of allBoxes) {
    if (!solidBox(b) || b.y2 <= feet + 0.55 || b.y1 >= feet + 1.75) continue;
    const cx = clamp(x, b.x1, b.x2), cz = clamp(z, b.z1, b.z2);
    if ((x - cx) ** 2 + (z - cz) ** 2 < rad * rad) return true;
  }
  return false;
}
function rampH(r, x, z) {
  const x0 = r.x0, z0 = r.z0; if (x < x0 || x > x0 + 3 || z < z0 || z > z0 + 3) return -1;
  const t = r.d === 0 ? (z0 + 3 - z) / 3 : r.d === 1 ? (x - x0) / 3 : r.d === 2 ? (z - z0) / 3 : (x0 + 3 - x) / 3;
  return r.y0 + 3 * t;
}
function groundAt(x, z, rad, feet) {
  let g = (levelData && levelData.smash) ? -1e6 : 0;
  for (const b of allBoxes) {
    if (!solidBox(b) || b.y2 > feet + 0.6) continue;
    const cx = clamp(x, b.x1, b.x2), cz = clamp(z, b.z1, b.z2);
    if ((x - cx) ** 2 + (z - cz) ** 2 < (rad * 0.6) ** 2) g = Math.max(g, b.y2);
  }
  for (const r of ramps) { const h = rampH(r, x, z); if (h >= 0 && h <= feet + 0.6) g = Math.max(g, h); }
  return g;
}
function moveCircle(o, dx, dz, rad, feet) {
  let moved = false;
  if (dx && !collides(o.x + dx, o.z, rad, feet)) { o.x += dx; moved = true; }
  if (dz && !collides(o.x, o.z + dz, rad, feet)) { o.z += dz; moved = true; }
  return moved;
}
function rayBox(o, d, b, maxT) {
  let tmin = 0, tmax = maxT;
  const ax = [['x', b.x1, b.x2], ['y', b.y1, b.y2], ['z', b.z1, b.z2]];
  for (const [k, mn, mx] of ax) {
    if (Math.abs(d[k]) < 1e-9) { if (o[k] < mn || o[k] > mx) return null; }
    else { let t1 = (mn - o[k]) / d[k], t2 = (mx - o[k]) / d[k]; if (t1 > t2) [t1, t2] = [t2, t1]; tmin = Math.max(tmin, t1); tmax = Math.min(tmax, t2); if (tmin > tmax) return null; }
  }
  return tmin;
}
