// ---- portals
const portalTime = { value: 0 };
function portalMaterial(c1, c2) {
  return new THREE.ShaderMaterial({
    uniforms: { time: portalTime, c1: { value: new THREE.Color(c1) }, c2: { value: new THREE.Color(c2) }, on: { value: 1 } },
    vertexShader: 'varying vec2 vUv; void main(){ vUv = uv; gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0); }',
    fragmentShader: `uniform float time, on; uniform vec3 c1, c2; varying vec2 vUv;
      void main(){ vec2 p = vUv - 0.5; float r = length(p) * 2.0; float a = atan(p.y, p.x);
        float sw = sin(a * 3.0 + r * 9.0 - time * 3.5) * 0.5 + 0.5; float sw2 = sin(a * 5.0 - r * 14.0 + time * 2.0) * 0.5 + 0.5;
        vec3 col = mix(c1, c2, sw * 0.7 + sw2 * 0.3); col += vec3(1.0) * smoothstep(0.25, 0.0, r) * 0.2 * on;
        float rim = smoothstep(0.82, 1.0, r) * (1.0 - smoothstep(0.98, 1.0, r));
        float alpha = (smoothstep(1.0, 0.9, r) * (0.35 + 0.5 * sw) * mix(0.25, 1.0, on)) + rim;
        gl_FragColor = vec4(col * (0.3 + 0.55 * on), alpha * 0.75); }`,
    transparent: true, depthWrite: false, side: THREE.DoubleSide, blending: THREE.AdditiveBlending
  });
}
function makePortal(r, c1, c2) {
  const g = new THREE.Group();
  const disc = new THREE.Mesh(new THREE.CircleGeometry(r, 48), portalMaterial(c1, c2)); g.add(disc);
  const frame = new THREE.Mesh(new THREE.TorusGeometry(r * 1.03, r * 0.06, 10, 48), new THREE.MeshStandardMaterial({ color: 0x2a2f3a, metalness: 0.85, roughness: 0.3, envMap, envMapIntensity: 0.5 })); g.add(frame);
  const glow = new THREE.Mesh(new THREE.TorusGeometry(r * 1.0, r * 0.025, 8, 48), new THREE.MeshBasicMaterial({ color: c1 })); g.add(glow);
  for (let k = 0; k < 8; k++) { const a = k / 8 * Math.PI * 2, n = new THREE.Mesh(RBox(r * 0.12, r * 0.2, r * 0.1), new THREE.MeshBasicMaterial({ color: c2 })); n.position.set(Math.cos(a) * r * 1.08, Math.sin(a) * r * 1.08, 0); n.rotation.z = a; g.add(n); }
  g.userData = { disc, glow };
  return g;
}

