  const gunHolder = new THREE.Group(); gunHolder.position.set(0.06, -0.1, -0.5); aim.add(gunHolder);
  const beam = new THREE.Mesh(new THREE.ConeGeometry(1.7, 9, 24, 1, true), new THREE.MeshBasicMaterial({ color: 0xfff2c0, transparent: true, opacity: 0.0, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide }));
