  m.position.copy(p); m.scale.setScalar(0.3); scene.add(m); fxList.push({ o: m, t: 0.45, life: 0.45, kind: 'boom', r });
  const L = flashLights[flashIdx++ % 2]; L.position.copy(p); L.color.setHex(color); L.intensity = 3.5;
