    if (Math.hypot(itemObj.x - me.x, itemObj.z - me.z) < 1.3 && !me.dead) { itemObj.taken = true; itemObj.g.visible = false; S.items++; SAVE.milo[world.ch - 1] = true; saveGame(); if (S.items >= 6) unlock('milo'); const it = CH[world.ch - 1].item; sfx.up(); banner(it.name.toUpperCase(), 'Audio log recovered'); radio(['JUNO|' + it.text]); }
