  if (amHost && !isHost) { hostSince = Date.now(); for (const k in lastRs) delete lastRs[k]; if (!world) world = wantBattle ? newBattle(Math.max(1, peersList.length), wantBattle) : newWorld(+$('#startCh').value || 1, Math.max(1, peersList.length), null, SET.diff); }
