    dm: { ep: curEp, d: myDmg.map(v => Math.round(v || 0)) }, fx: me.fx, wp: sl ? sl.id : 'pistol', wr: sl ? sl.r : 0, bx: me.bx, rs: me.rs,
    bp: myPieces.map(p => [p.t, p.cx, p.cz, p.lv, p.d]), st: allStun(), an: me.aiming ? 1 : 0, k: me.kills || 0, dc: me.dc || 0, kb: me.kb || null, pd: me.pd || null, pc: Math.round(me.pct || 0), rf: me.rf || 0, rcp: me.rcp || 0, sp: performance.now() < (me.spawnProt || 0) ? 1 : 0, pzi: me.pzi || null,
