  g.clearRect(0, 0, 170, 170); g.fillStyle = 'rgba(20,12,30,.8)'; g.fillRect(0, 0, 170, 170);
  for (const b of levelBoxes) { if (b.kind === 'outer') continue; g.fillStyle = b.kind === 'furn' ? 'rgba(160,140,200,.25)' : b.kind === 'door' ? ((b.did !== undefined ? !doorOpenBit(b.did) : doorClosed()) ? '#ff4d6d' : '#5ee08a') : 'rgba(200,180,240,.55)'; g.fillRect(X(b.x1), Z(b.z1), (b.x2 - b.x1) * s, Math.max(1.5, (b.z2 - b.z1) * s)); }
