// ======================================================= META: save, achievements, stats, journal
const SAVE = { unlocked: 1, ach: {}, diary: [], milo: [], tot: { head: 0, freeze: 0, build: 0, chest: 0, kills: 0 }, best: {} };
try { const s = JSON.parse(localStorage.getItem('riftspire_save') || '{}'); Object.assign(SAVE, s); SAVE.tot = Object.assign({ head: 0, freeze: 0, build: 0, chest: 0, kills: 0 }, s.tot || {}); } catch (e) {}
