    const d = [[Math.abs(p.x - b.x1), -1, 0, 0], [Math.abs(p.x - b.x2), 1, 0, 0], [Math.abs(p.y - b.y2), 0, 1, 0], [Math.abs(p.z - b.z1), 0, 0, -1], [Math.abs(p.z - b.z2), 0, 0, 1]].sort((a, c) => a[0] - c[0])[0];
