  if (id === 'BOLT') { const g = new THREE.Group(), b = new THREE.Group(); b.position.y = 1.3; g.add(b); const P = buildDrone(b, 1.1); P.eye.material = EM.glow(0x38e1ff, 1.8); outline(b, 0.02); g.userData = { P, body: b, float: true }; return g; }
