  if (id === 'VAEL' || id === 'MIRA') { const hat = new THREE.Mesh(new THREE.ConeGeometry(0.32, 0.8, 16), M(id === 'VAEL' ? 0x2a3a9a : 0x5a2a8a)); hat.position.y = 0.5; hg.add(hat); const brim = new THREE.Mesh(new THREE.CylinderGeometry(0.48, 0.48, 0.04, 20), M(id === 'VAEL' ? 0x2a3a9a : 0x5a2a8a)); brim.position.y = 0.16; hg.add(brim); }
  if (id === 'VAEL') { const beard = new THREE.Mesh(new THREE.ConeGeometry(0.2, 0.5, 10), M(0xf0f4ff)); beard.rotation.x = Math.PI; beard.position.set(0, -0.3, -0.18); hg.add(beard); }
  if (id === 'OKOYE') { for (const ex of [-0.1, 0.1]) { const gl = new THREE.Mesh(new THREE.TorusGeometry(0.08, 0.015, 6, 16), M(0x222222)); gl.position.set(ex, -0.02, -0.29); hg.add(gl); } const bun = new THREE.Mesh(new THREE.SphereGeometry(0.16, 12, 10), M(0x1a1010)); bun.position.set(0, 0.25, 0.15); hg.add(bun); }
  if (id === 'ROURKE') { const beard = new THREE.Mesh(RBox(0.4, 0.18, 0.12), M(0x6a4a3a)); beard.position.set(0, -0.2, -0.22); hg.add(beard); g.scale.setScalar(1.12); }
  if (id === 'JUNO') { const gog = new THREE.Mesh(new THREE.TorusGeometry(0.3, 0.035, 6, 24), M(0x38e1ff)); gog.rotation.x = Math.PI / 2; gog.position.y = 0.12; hg.add(gog); const hair = new THREE.Mesh(new THREE.SphereGeometry(0.2, 12, 10), M(0x3a2010)); hair.position.set(0, -0.05, 0.22); hg.add(hair); }
  outline(g, 0.025);
