    if (b.kind === 'ped') { const g = new THREE.Group(); g.add(mesh(new THREE.CylinderGeometry(0.4, 0.5, b.y2, 12), M.marble, (b.x1 + b.x2) / 2, b.y2 / 2, (b.z1 + b.z2) / 2)); outline(g, 0.03); level.add(g); }
