    const tag = nameSprite(n.id === 'BOLT' ? 'Bolt' : (SPEAKER_NAME[n.id] || n.id).split(' · ')[0], '#ffd27a'); tag.position.y = n.id === 'BOLT' ? 2.1 : 2.75; g.add(tag);
