// ======================================================= MAIN LOOP
let last = performance.now(), titleT = 0, timeScale = 1, slowUntil = 0, fpsN = 0, fpsT = 0;
function slowMo() { slowUntil = performance.now() + 900; }
buildLevel(1, 4242);
function frame(now) {
  const rdt = Math.min(0.05, (now - last) / 1000); last = now;
  timeScale += ((now < slowUntil ? 0.25 : 1) - timeScale) * Math.min(1, rdt * 10);
  const dt = rdt * timeScale;
  try {
    pollGamepad(); tickMusic(); portalTime.value = now / 1000; storyStep(); foeIntros(); tutStep(dt); meleeTick(dt); companionTick(dt, now); bossArrival(now); cheatTick(dt); buildCheck(); owTick(dt, now); rlTick(dt, now); smashTick(dt, now); atkTick(); raceTick(dt, now);
    if (mode === 'title') { titleFrame(rdt, now); } else {
      if (mode === 'net' && nroom) netStep(now); else isHost = true;
      const players = getPlayers();
      const frozen = (mode === 'solo' && !!world && (!!dlg || paused || overlayOpen())) || (CHEAT.freeze && isHost && !!world);
      const pFrozen = mode === 'solo' && !!world && (!!dlg || paused || overlayOpen());
      if (frozen) { world.phEnd += rdt * 1000; if (world.E) world.E.forEach(e => { if (e.stunUntil > now) e.stunUntil += rdt * 1000; }); }
      const sdt = frozen ? 0 : dt;
      if (isHost && world && !frozen) hostStep(mode === 'net' ? rdt : dt, now, players);
      syncWorld(now);
      if (world && world.mode === 'battle' && !world.race) processPvP(players, now);
      if (!frozen) processShots(now);
      syncPieces(players);
      localStep(pFrozen ? 0 : dt, now);
      updatePreview();
      updatePlayerProj(pFrozen ? 0 : dt, now); updateEnemyProj(sdt, now); updateHazards(sdt, now);
      updatePickups(sdt, now);
      updateEnemyMeshes(sdt, now);
      updateLevelExtras(sdt, now); puzzleEvents();
      updateAvatars(dt, now, players);
      updateCasings(dt);
      publish(now);
      hud(now, players);
    }
    updateParticles(dt); updateAtmos(dt, now); updateFx(dt); updateDmgNums(rdt);
    renderFrame(now);
    fpsN++; if (now - fpsT > 500) { $('#fps').textContent = SET.fps ? Math.round(fpsN * 1000 / (now - fpsT)) + ' fps' : ''; fpsN = 0; fpsT = now; }
  } catch (err) { console.error(err); }
  requestAnimationFrame(frame);
}

