  try { room = (window.claude && window.claude.use) ? await window.claude.use('room') : null; } catch (e) { room = null; }
  if (!room && window.__p2p) room = window.__p2p;
  if (room) { $('#join').disabled = false; $('#join').textContent = 'Join co-op crew'; $('#bJoin').disabled = false; $('#bJoin').textContent = 'Join online battle'; }
  else { $('#bJoin').textContent = 'Online battle unavailable here'; $('#join').textContent = 'Co-op unavailable here'; $('#joinnote').textContent = "Online play couldn't start here (the multiplayer library didn't load, or this page was opened as a local file). Host the page on a website to play with friends. Solo works everywhere."; }
