function fillStart() {
  const s = $('#startCh'); s.replaceChildren(); const box = $('#levels'); box.replaceChildren();
  const max = Math.min(NCH, SAVE.unlocked || 1);
  CH.forEach((c, k) => {
    if (k >= NCH) { const o = document.createElement('option'); o.value = k + 1; o.textContent = c.name; s.appendChild(o); return; }
    const i = k + 1, o = document.createElement('option'); o.value = i; o.textContent = c.name; s.appendChild(o);
    const b = document.createElement('button'); b.className = 'lv' + (i === 1 ? ' on' : '') + (i > max ? ' locked' : '');
    const sm = document.createElement('small'); sm.textContent = c.code; const nm = document.createElement('b'); nm.textContent = i > max ? 'Locked' : c.name; b.append(sm, nm);
    if (c.boss && i <= max) { const bs = document.createElement('span'); bs.className = 'boss'; bs.textContent = 'Boss: ' + c.boss; b.appendChild(bs); }
    b.addEventListener('click', () => { if (i > max) return; s.value = i; box.querySelectorAll('.lv').forEach(x => x.classList.remove('on')); b.classList.add('on'); sfx.ui(); });
    box.appendChild(b);
  });
  s.value = 1;
  const logs = SAVE.milo.filter(Boolean).length, pages = SAVE.diary.filter(Boolean).length, ach = Object.keys(SAVE.ach).length;
  const best = SAVE.best[SET.diff || 'normal'];
  $('#progress').textContent = `Highest level reached: ${max} / ${NCH} · Juno's logs ${logs} / 9 · Grimoire pages ${pages} / ${NCH} · Achievements ${ach} / ${ACH.length}${best ? ` · Best ${DIFFS[SET.diff || 'normal'].n} clear ${fmt(best.time)}` : ''}`;
}
