  if (Math.abs(camera.fov - 55) > 0.1) { camera.fov = 55; camera.updateProjectionMatrix(); }
  player.visible = true; player.rotation.y = Math.PI + Math.sin(tAnimT * 0.5) * 0.15;
  animChar(player, dt, 0, false, -0.05 + Math.sin(tAnimT * 0.8) * 0.03, false, 0);
