function rimify(root, color, strength) {
  const c = new THREE.Color(color);
  root.traverse(o => { if (!o.isMesh || o.userData.ink) return; const m = o.material; if (!m || !m.isMeshToonMaterial || m.userData.rim) return; m.userData.rim = true;
    m.onBeforeCompile = sh => { sh.uniforms.rimColor = { value: c }; sh.fragmentShader = 'uniform vec3 rimColor;\n' + sh.fragmentShader.replace('gl_FragColor = vec4( outgoingLight, diffuseColor.a );', `float rimF = 1.0 - max(dot(normal, normalize(vViewPosition)), 0.0); outgoingLight += rimColor * pow(rimF, 3.0) * ${strength.toFixed(2)};\n\tgl_FragColor = vec4( outgoingLight, diffuseColor.a );`); };
    m.customProgramCacheKey = () => 'rim' + strength.toFixed(2); });
}
