  P.arms[1].rotation.x = -0.3 - u.wu * 2.2 + u.atk * 2.6; P.arms[1].rotation.z = -0.2; P.arms[1].userData.el.rotation.x = -0.4 - u.wu * 0.4;
  P.torso.rotation.y = -u.wu * 0.25 + u.atk * 0.4;
  P.plume.rotation.x = Math.sin(tt * 3) * 0.08 - Math.min(0.4, c.vel * 0.08);
  u.block = Math.max(0, (u.block || 0) - c.dt * 3);
  const off = c.st;
