  // guard pose while holding right-click
  gun.rotation.z += VM.ads * 1.3; gun.rotation.x -= VM.ads * 0.45; gun.position.y += VM.ads * 0.12;
  if (ud.edges) { const g = 0.75 + Math.sin(performance.now() / 120) * 0.25; ud.edges.forEach(e => e.scale.set(1, g + 0.3, 1)); }
  trailMat.opacity = Math.max(0, trailMat.opacity - dt * 6);
