  const o = camera.position, f = camFwd(), out = [], cosC = Math.cos(W.cone);
  for (const id in avatars) { const a = avatars[id]; if (a.userData.dead) continue;
    for (const s of avatarSpheres(a)) { const vx = s.c.x - o.x, vy = s.c.y - o.y, vz = s.c.z - o.z, d = Math.hypot(vx, vy, vz) || 1e-3; if (d - s.r > W.reach) continue; const dot = (vx * f.x + vy * f.y + vz * f.z) / d; if (dot < cosC) continue; out.push({ pv: id, head: !!s.head && dot > 0.95, pt: new THREE.Vector3(s.c.x, s.c.y, s.c.z) }); break; } }
