let lastRa = 0;
function storyStep() {
  if (TUT || !world || world.mode === 'battle' || !levelData || levelData.kind !== 'level' || dlg || mode === 'title' || me.dead) return;
  const evs = STORY_EV[world.ch] || [];
  evs.forEach((ev, i) => {
    const key = world.ep + ':' + i; if (firedEv[key]) return;
    let go = false;
    if (ev.on === 'start') go = world.ph === 'fight';
    else if (ev.on === 'room4') go = roomAt(me.x, me.z) === 4 && world.ph === 'fight';
    else if (ev.on === 'clear') go = world.ph === 'clear';
    else if (ev.on.startsWith('talked:')) { const id = ev.on.slice(7); go = npcObjs.some(o => o.n.id === id && o.talked); }
    if (!go) return; firedEv[key] = true;
    startDialogue(ev.lines(), ev.act);
  });
  for (const o of npcObjs) { const as = o.n.afterSolved; if (!as || o.rewarded || !o.talked) continue; const k = levelData.puzzles.findIndex(p => p.type === as.type); if (k >= 0 && world.P[k] && world.P[k].solved && Math.hypot(o.n.x - me.x, o.n.z - me.z) < 3) { o.rewarded = true; startDialogue(as.lines, as.act); } }
}
function outroFor() { const e = STORY.ending || (S.bolt ? 'bolt' : 'quiet'); STORY.ending = e; unlock('end_' + e); return ENDINGS[e].lines; }
