function bossPortrait(kind) {
  const c = document.createElement('canvas'); c.width = c.height = 108; const g = c.getContext('2d');
  const bg = g.createRadialGradient(54, 50, 4, 54, 54, 70); bg.addColorStop(0, kind === 'LIBRARIAN' ? '#4a2a5a' : '#5a2a1a'); bg.addColorStop(1, '#0a0610'); g.fillStyle = bg; g.fillRect(0, 0, 108, 108);
  const circ = (x, y, rr, col) => { g.fillStyle = col; g.beginPath(); g.arc(x, y, rr, 0, 6.28); g.fill(); };
  if (kind === 'LIBRARIAN') { g.fillStyle = '#6b3fa0'; g.beginPath(); g.moveTo(54, 14); g.lineTo(88, 100); g.lineTo(20, 100); g.fill(); circ(54, 52, 20, '#2a1838'); circ(46, 50, 4, '#ffd27a'); circ(62, 50, 4, '#ffd27a'); g.strokeStyle = '#ffd27a'; g.lineWidth = 3; g.beginPath(); g.arc(54, 30, 22, 3.6, 5.8); g.stroke(); g.fillStyle = '#c8a46a'; g.fillRect(36, 80, 36, 8); }
  else { g.fillStyle = '#6a6070'; g.fillRect(24, 28, 60, 60); g.fillStyle = '#d0a040'; g.fillRect(22, 26, 64, 10); circ(42, 56, 7, '#ff4d2a'); circ(66, 56, 7, '#ff4d2a'); g.fillStyle = '#2a2f3a'; g.fillRect(36, 72, 36, 6); }
  return c.toDataURL();
}
