  shopStock.forEach((it, k) => { if (!it) return; const W = WEAPONS[it.id], pr = priceOf(it); add('#shB', `<b style="color:${RAR[it.r].c}">${RAR[it.r].n} ${W.name}</b>`, '🪙 ' + pr, p.coins >= pr, () => { p.coins -= pr; spawnPickup('weapon', me.x - Math.sin(me.yaw) * 1.4, me.z - Math.cos(me.yaw) * 1.4, { id: it.id, r: it.r }); shopStock[k] = null; toast('Bought! It is on the ground in front of you.', '#5ee08a'); saveGame(); }, gunIcon(it.id, it.r)); });
  add('#shB', 'Healing potion (full health)', '🪙 30', p.coins >= 30 && me.hp < S.maxHp, () => { p.coins -= 30; me.hp = S.maxHp; saveGame(); });
